using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class StudioHeistTests
    {
        static StudioHeistOptions C()=>StudioHeistOptions.Defaults();
        static WalletData W()=>new WalletData{Bank=100,Cash=777};
        static StudioHeistFlow Complete(string id,int act){var f=new StudioHeistFlow(id,act);int count=0;while(f.Objective!=StudioObjective.Ready){Assert.True(f.Advance(f.Objective,true));Assert.True(++count<20);}return f;}
        static WalletData Begin(int act=0){var w=W();for(int i=0;i<=act;i++){Assert.True(StudioHeistTransactions.Begin(w,"act"+i,i,C(),i==5?325000:0,()=>{},out _));if(i<act){Assert.True(StudioHeistTransactions.Ready(w,Complete("act"+i,i),()=>{},out _));Assert.True(StudioHeistTransactions.Finish(w,"act"+i,"prepared",()=>{},out _));}}return w;}
        [Fact]public void DefaultsMatchReferenceModelsLocationsAndAllSixActs(){var c=C();Assert.True(c.Valid);Assert.Equal("locust",c.GetawayModel);Assert.Equal("burrito3",c.VanModel);Assert.Equal("boattrailer2",c.TrailerModel);Assert.Equal("dinghy3",c.EscapeBoatModel);Assert.Equal(873.0571f,c.Van.X);Assert.Equal(-326.7225f,c.Lockup.X);Assert.Equal(717.1277f,c.Plant.X);Assert.Equal(-3739.829f,c.BuyerBoat.X);Assert.Equal(4,c.Directors.Count);Assert.Equal(4,c.SupplyGuards.Count);Assert.Equal(6,c.DockGuards.Count);Assert.Equal(18,c.StudioGuards.Count);Assert.Equal(200000,c.MinReward);Assert.Equal(450000,c.MaxReward);}
        [Fact]public void OldWalletAndUnknownDataStayOptional(){var w=JsonConvert.DeserializeObject<WalletData>("{\"Cash\":8,\"Bank\":99,\"Future\":42}");Assert.Null(w.StudioHeist);Assert.False(StudioHeistTransactions.Begin(w,"skip",5,C(),200000,()=>throw new Exception(),out _));Assert.Null(w.StudioHeist);Assert.Equal(42,(int)w.Extra["Future"]);}
        [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]
        public void ActMustProveItsOrderedStepsBeforeReadyOrPayment(int act){var w=Begin(act);string id="act"+act;var f=new StudioHeistFlow(id,act);Assert.False(StudioHeistTransactions.Ready(w,f,()=>throw new Exception(),out _));Assert.False(StudioHeistTransactions.Finish(w,id,act==5?"paid":"prepared",()=>throw new Exception(),out _));Assert.False(f.Advance(StudioObjective.Ready,true));Assert.False(f.Advance(f.Objective,false));Assert.True(StudioHeistTransactions.Ready(w,Complete(id,act),()=>{},out _));Assert.True(w.StudioHeist.Pending.Ready);Assert.True(StudioHeistTransactions.Finish(w,id,act==5?"paid":"prepared",()=>{},out _));Assert.Equal(act==5?325100:100,w.Bank);Assert.Equal(777,w.Cash);}
        [Fact]public void PreparationsDoNotPayAndFinalResetsOnlyAfterBankCommit(){var w=Begin(5);Assert.Equal(5,w.StudioHeist.Setups);Assert.Equal(100,w.Bank);Assert.Equal(5,w.StudioHeist.Completed);StudioHeistTransactions.Ready(w,Complete("act5",5),()=>{},out _);Assert.True(StudioHeistTransactions.Finish(w,"act5","paid",()=>{},out bool changed));Assert.True(changed);Assert.Equal(325100,w.Bank);Assert.Equal(0,w.StudioHeist.Setups);Assert.Equal(6,w.StudioHeist.Completed);Assert.Equal(1,w.StudioHeist.Heists);Assert.Equal(325000,w.StudioHeist.Earned);Assert.True(w.StudioHeist.Valid);}
        [Fact]public void ReadyReloadCanCollectExactlyOnceWithoutRespawningMission(){var w=Begin(5);StudioHeistTransactions.Ready(w,Complete("act5",5),()=>{},out _);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));int saves=0;Assert.True(StudioHeistTransactions.Finish(w,"act5","paid",()=>saves++,out _));Assert.True(StudioHeistTransactions.Finish(w,"act5","paid",()=>throw new Exception(),out bool changed));Assert.False(changed);Assert.Equal(325100,w.Bank);Assert.Equal(1,saves);Assert.False(StudioHeistTransactions.Finish(w,"act5","failed",()=>throw new Exception(),out _));}
        [Theory][InlineData("failed")][InlineData("cancelled")]
        public void FailureOrCancelPreservesPreviousPreparationsButNotAttemptPayout(string result){var w=Begin(4);Assert.True(StudioHeistTransactions.Finish(w,"act4",result,()=>{},out _));Assert.Equal(4,w.StudioHeist.Setups);Assert.Null(w.StudioHeist.Pending);Assert.Equal(100,w.Bank);Assert.True(StudioHeistTransactions.Begin(w,"retry",4,C(),0,()=>{},out _));Assert.False(StudioHeistTransactions.Begin(w,"skip",5,C(),325000,()=>throw new Exception(),out _));Assert.True(w.StudioHeist.Valid);}
        [Fact]public void SnapshotAndRewardDoNotChangeWhenConfigurationChanges(){var w=W();var c=C();Assert.True(StudioHeistTransactions.Begin(w,"first",0,c,0,()=>{},out _));c.SecondsLimit=600;c.Van.X=10;Assert.Equal(1800,w.StudioHeist.Pending.Options.SecondsLimit);Assert.Equal(873.0571f,w.StudioHeist.Pending.Options.Van.X);var pending=w.StudioHeist.Pending;Assert.False(StudioHeistTransactions.Begin(w,"reroll",0,c,0,()=>throw new Exception(),out _));Assert.Same(pending,w.StudioHeist.Pending);}
        [Fact]public void DeadlineCheckpointsAreMonotoneAbsoluteAndDoNotCreditOffline(){var w=Begin();Assert.True(StudioHeistTransactions.Checkpoint(w,"act0",5000,()=>{},out _));Assert.False(StudioHeistTransactions.Checkpoint(w,"act0",0,()=>throw new Exception(),out _));Assert.True(StudioHeistTransactions.Checkpoint(w,"act0",5000,()=>throw new Exception(),out bool changed));Assert.False(changed);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.Equal(5000,w.StudioHeist.Pending.Elapsed);Assert.True(StudioHeistTransactions.Checkpoint(w,"act0",1800000,()=>{},out _));Assert.False(StudioHeistTransactions.Ready(w,Complete("act0",0),()=>throw new Exception(),out _));Assert.True(StudioHeistTransactions.Finish(w,"act0","failed",()=>{},out _));}
        [Fact]public void WrongAttemptOrWrongActCannotProveCompletion(){var w=Begin();Assert.False(StudioHeistTransactions.Ready(w,Complete("wrong",0),()=>throw new Exception(),out _));Assert.False(StudioHeistTransactions.Ready(w,Complete("act0",1),()=>throw new Exception(),out _));Assert.False(StudioHeistTransactions.Checkpoint(w,null,0,()=>throw new Exception(),out _));Assert.False(StudioHeistTransactions.Checkpoint(W(),null,0,()=>throw new Exception(),out _));}
        [Theory][InlineData("begin")][InlineData("checkpoint")][InlineData("ready")][InlineData("prepared")][InlineData("paid")][InlineData("failed")][InlineData("cancelled")]
        public void EverySaveFailureRestoresBankRecordAndPreparationCounters(string step){var w=step=="begin"?W():Begin(step=="paid"?5:0);string id=step=="paid"?"act5":"act0";if(step=="paid" || step=="prepared")StudioHeistTransactions.Ready(w,Complete(id,step=="paid"?5:0),()=>{},out _);string before=JsonConvert.SerializeObject(w);Action fail=()=>throw new InvalidOperationException();Assert.Throws<InvalidOperationException>(()=>{switch(step){case "begin":StudioHeistTransactions.Begin(w,id,0,C(),0,fail,out _);break;case "checkpoint":StudioHeistTransactions.Checkpoint(w,id,5000,fail,out _);break;case "ready":StudioHeistTransactions.Ready(w,Complete(id,0),fail,out _);break;default:StudioHeistTransactions.Finish(w,id,step,fail,out _);break;}});Assert.Equal(before,JsonConvert.SerializeObject(w));}
        [Fact]public void BankOverflowConservesEarnedReadyPayoutForRetry(){var w=Begin(5);StudioHeistTransactions.Ready(w,Complete("act5",5),()=>{},out _);w.Bank=int.MaxValue-325000+1;Assert.False(StudioHeistTransactions.Finish(w,"act5","paid",()=>throw new Exception(),out _));Assert.True(w.StudioHeist.Pending.Ready);Assert.Equal(5,w.StudioHeist.Setups);w.Bank=0;Assert.True(StudioHeistTransactions.Finish(w,"act5","paid",()=>{},out _));Assert.Equal(325000,w.Bank);}
        [Fact]public void UnknownFieldsAndOtherSystemsSurvivePayout(){var w=Begin(5);var j=JObject.FromObject(w);j["FutureWallet"]=42;j["StudioHeist"]["FutureBook"]="keep";j["StudioHeist"]["Pending"]["Options"]["FutureOptions"]=77;w=j.ToObject<WalletData>();w.Traffic=new TrafficData();w.Custody=new CustodyData();string police=JsonConvert.SerializeObject(new[]{(object)w.Traffic,w.Custody});StudioHeistTransactions.Ready(w,Complete("act5",5),()=>{},out _);Assert.Equal(77,(int)w.StudioHeist.Pending.Options.Extra["FutureOptions"]);StudioHeistTransactions.Finish(w,"act5","paid",()=>{},out _);Assert.Equal(42,(int)w.Extra["FutureWallet"]);Assert.Equal("keep",(string)w.StudioHeist.Extra["FutureBook"]);Assert.Equal(police,JsonConvert.SerializeObject(new[]{(object)w.Traffic,w.Custody}));}
        [Fact]public void HistoryPrunesReceiptsWithoutChangingLifetimeTotals(){var w=W();for(int cycle=0;cycle<7;cycle++)for(int act=0;act<6;act++){string id=cycle+":"+act;Assert.True(StudioHeistTransactions.Begin(w,id,act,C(),act==5?200000:0,()=>{},out _));StudioHeistTransactions.Ready(w,Complete(id,act),()=>{},out _);Assert.True(StudioHeistTransactions.Finish(w,id,act==5?"paid":"prepared",()=>{},out _));}Assert.Equal(32,w.StudioHeist.History.Count);Assert.Equal(42,w.StudioHeist.Completed);Assert.Equal(7,w.StudioHeist.Heists);Assert.Equal(1400100,w.Bank);Assert.True(w.StudioHeist.Valid);}
        [Fact]public void CorruptRecordsAndOverflowsAreProtected(){var w=Begin();w.StudioHeist.Setups=5;Assert.False(w.StudioHeist.Valid);Assert.False(StudioHeistTransactions.Finish(w,"act0","failed",()=>throw new Exception(),out _));w=W();w.StudioHeist=new StudioHeistData{Started=long.MaxValue,Failed=long.MaxValue};Assert.True(w.StudioHeist.Valid);Assert.False(StudioHeistTransactions.Begin(w,"overflow",0,C(),0,()=>throw new Exception(),out _));}
        [Theory][InlineData(20,false)][InlineData(21,true)][InlineData(0,true)][InlineData(4,true)][InlineData(5,false)][InlineData(24,false)][InlineData(-1,false)]
        public void DocumentStartUsesReferenceNightWindow(int hour,bool night){Assert.Equal(night,StudioHeistRules.Night(hour));}
        [Fact]public void ThreeTimedLockpickHitsRequiredAndFiveMissesFail(){var p=new StudioLockpick();for(int i=0;i<4;i++)p.Tick(1000,true);Assert.True(p.Press());for(int i=0;i<3;i++)p.Tick(1000,true);p.Tick(200,true);Assert.True(p.Press());p.Tick(1000,true);p.Tick(1000,true);p.Tick(400,true);Assert.True(p.Press());Assert.True(p.Complete);Assert.False(p.Press());p=new StudioLockpick();for(int i=0;i<5;i++)Assert.False(p.Press());Assert.True(p.Failed);}
        [Fact]public void LockpickDoesNotAdvanceWhilePausedOrAfterStallAndResetsSuccessOnMiss(){var p=new StudioLockpick();p.Tick(4000,true);Assert.Equal(0,p.Elapsed);for(int i=0;i<4;i++)p.Tick(1000,true);p.Tick(1000,false);Assert.Equal(.8f,p.Position);p.Press();Assert.Equal(1,p.Solved);p.Press();Assert.Equal(0,p.Solved);Assert.Equal(1,p.Failures);}
        [Theory][InlineData(true,true,true,0,5,true)][InlineData(false,true,true,0,0,false)][InlineData(true,false,true,0,0,false)][InlineData(true,true,false,0,0,false)][InlineData(true,true,true,.5f,0,false)][InlineData(true,true,true,0,5.1f,false)]
        public void VehicleHandoverRequiresExactOwnDriverStoppedAndNoPolice(bool driver,bool own,bool noPolice,float speed,float distance,bool expected){Assert.Equal(expected,StudioHeistRules.Delivery(driver,own,noPolice,speed,distance));}
        [Fact]public void SeaHandoverRejectsPassengerWrongBuyerSpeedAndStars(){Assert.True(StudioHeistRules.Sea(true,true,true,true,1,12));Assert.False(StudioHeistRules.Sea(false,true,true,true,0,0));Assert.False(StudioHeistRules.Sea(true,true,false,true,0,0));Assert.False(StudioHeistRules.Sea(true,true,true,false,0,0));Assert.False(StudioHeistRules.Sea(true,true,true,true,1.5f,0));Assert.False(StudioHeistRules.Sea(true,true,true,true,float.NaN,0));}
        [Fact]public void InvalidOptionsAndReadyOutcomeCannotBypassValidation(){var c=C();c.Directors=null;Assert.False(c.Valid);Assert.False(StudioHeistTransactions.Begin(W(),"bad",0,c,0,()=>throw new Exception(),out _));c=C();c.MaxReward=int.MaxValue;Assert.False(c.Valid);var w=Begin();Assert.False(StudioHeistTransactions.Finish(w,"act0","paid",()=>throw new Exception(),out _));Assert.False(StudioHeistTransactions.Finish(w,"act0","unknown",()=>throw new Exception(),out _));}
        [Fact]public void StudioGateCannotOverlapPoliceOrAnyJob(){var g=new ShiftGate();Assert.True(g.Acquire("studio_heist"));foreach(string name in new[]{"pizza","pilot","traffic","custody","gang_turf"})Assert.False(g.Acquire(name));g.Release("police");Assert.Equal("studio_heist",g.Owner);g.Release("studio_heist");Assert.True(g.Acquire("custody"));}
        static StudioHeistFlow EscapeFlow(){var f=new StudioHeistFlow("act5",5);while(f.Objective!=StudioObjective.EscapeStudio)f.Advance(f.Objective,true);return f;}
        [Fact]public void DiversionOnlyDuringFinalEscapeAndCanBeUsedOnce(){var w=Begin(5);Assert.False(StudioHeistTransactions.Diversion(w,new StudioHeistFlow("act5",5),false,()=>throw new Exception(),out _));var f=EscapeFlow();Assert.False(StudioHeistTransactions.Diversion(w,f,true,()=>throw new Exception(),out _));Assert.True(StudioHeistTransactions.Diversion(w,f,false,()=>{},out _));Assert.False(w.StudioHeist.Pending.DiversionUsed);Assert.True(StudioHeistTransactions.Diversion(w,f,true,()=>{},out bool changed));Assert.True(changed);Assert.True(StudioHeistTransactions.Diversion(w,f,true,()=>throw new Exception(),out changed));Assert.False(changed);Assert.Equal(100,w.Bank);Assert.True(w.StudioHeist.Valid);}
        [Fact]public void DiversionFailureRollsBackAndReloadKeepsRequestWithoutAward(){var w=Begin(5);var f=EscapeFlow();string before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>StudioHeistTransactions.Diversion(w,f,false,()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));StudioHeistTransactions.Diversion(w,f,false,()=>{},out _);w=JsonConvert.DeserializeObject<WalletData>(JsonConvert.SerializeObject(w));Assert.True(w.StudioHeist.Pending.DiversionRequested);Assert.False(w.StudioHeist.Pending.DiversionUsed);before=JsonConvert.SerializeObject(w);Assert.Throws<Exception>(()=>StudioHeistTransactions.Diversion(w,f,true,()=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(w));Assert.Equal(0,w.StudioHeist.Heists);}
    }
}
